<?php
require_once dirname(__DIR__) . '/auth.php';
require_once dirname(__DIR__) . '/app/data-slot.php';
require_once dirname(__DIR__) . '/app/beheer/editor-hulp.php';
if(!$ingelogd){header('Location: ../beheer.php');exit;}
$rechten=authRechten(['changelog'=>'Changelog'],[]);if(!$isMaster&&!in_array('changelog',$rechten['toegestaneTabs']??[],true)){http_response_code(403);echo'Geen toegang tot Changelog.';exit;}
$bestand=dirname(__DIR__).'/data/changelog.json';$vastPad=dirname(__DIR__).'/changelog-historie.php';$cats=['nieuw'=>'Nieuw','verbeterd'=>'Verbeterd','verbetering'=>'Verbeterd','opgelost'=>'Opgelost','beveiliging'=>'Beveiliging','onderhoud'=>'Onderhoud'];
function clEigen(string $pad):array{$d=beheerEditorLeesJson($pad,[]);return array_values(array_filter($d,'is_array'));}
function clSchrijf(string $pad,array $regels):bool{return beheerEditorSchrijfJson($pad,array_values($regels));}
$melding='';$type='';
if(($_SERVER['REQUEST_METHOD']??'')==='POST'){
 if(!csrfOk()){$melding='Sessie verlopen. Ververs de pagina en probeer opnieuw.';$type='fout';}
 else{$actie=(string)($_POST['actie']??'');$regels=clEigen($bestand);$slot=dataSlotOpen();try{$ok=false;if($actie==='toevoegen'||$actie==='bewerken'){$datum=beheerEditorDatumIso($_POST['datum']??'');if($datum==='')$datum=date('Y-m-d');$cat=(string)($_POST['cat']??'nieuw');if(!isset($cats[$cat])||$cat==='verbetering')$cat=$cat==='verbetering'?'verbeterd':'nieuw';$titel=beheerEditorKort($_POST['titel']??'',120);$tekst=beheerEditorKort($_POST['tekst']??'',500);if($titel===''){$melding='Vul een korte omschrijving in.';$type='fout';}else{if($actie==='toevoegen'){array_unshift($regels,['id'=>date('YmdHis').'-'.bin2hex(random_bytes(3)),'datum'=>$datum,'cat'=>$cat,'titel'=>$titel,'tekst'=>$tekst]);$log='toegevoegd: '.$titel;}else{$id=(string)($_POST['id']??'');$gevonden=false;foreach($regels as &$r){if((string)($r['id']??'')===$id){$r=['id'=>$id,'datum'=>$datum,'cat'=>$cat,'titel'=>$titel,'tekst'=>$tekst];$gevonden=true;break;}}unset($r);if(!$gevonden){$melding='Changelogregel niet gevonden.';$type='fout';}else$log='bijgewerkt: '.$titel;}if($melding==='')$ok=clSchrijf($bestand,$regels);}}
 elseif($actie==='verwijderen'){$id=(string)($_POST['id']??'');$voor=count($regels);$regels=array_values(array_filter($regels,static fn($r)=>(string)($r['id']??'')!==$id));if(count($regels)===$voor){$melding='Changelogregel niet gevonden.';$type='fout';}else{$ok=clSchrijf($bestand,$regels);$log='eigen regel verwijderd';}}
 else{$melding='Onbekende actie.';$type='fout';}
 if($ok){$melding='Changelog opgeslagen.';$type='ok';schrijfLog($logBestand,$huidigeGebruiker,'changelog',$log??$actie);}}
 finally{dataSlotDicht($slot);} }
}
$eigen=clEigen($bestand);$vast=is_file($vastPad)?require $vastPad:[];if(!is_array($vast))$vast=[];
?><!doctype html><html lang="nl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Changelog beheren</title><style>body{margin:0;background:#f6f2e8;color:#26351d;font-family:system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}.top{background:#fff;border-bottom:1px solid #ddd8c0;padding:16px 24px}.topin,.wrap{max-width:1050px;margin:auto}.topin{display:flex;justify-content:space-between}.top a{color:#2d6260;text-decoration:none;font-weight:700}.wrap{padding:30px 24px 70px}.kaart{background:#fff;border:1px solid #ddd8c0;border-radius:14px;padding:20px;margin-bottom:16px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.veld{margin-bottom:12px}.veld label{display:block;font-weight:700;font-size:12px;margin-bottom:5px}.veld input,.veld select,.veld textarea{width:100%;box-sizing:border-box;border:1px solid #cfcab7;border-radius:8px;padding:10px;font:inherit}.veld textarea{min-height:90px}.melding{padding:12px 14px;border-radius:9px;margin-bottom:18px}.ok{background:#e8f5ee;color:#205b38}.fout{background:#fdeceb;color:#8b2e27}.btn{border:0;border-radius:8px;padding:9px 14px;font-weight:700;cursor:pointer;background:#3a7a77;color:#fff}.danger{background:#a23b32}.meta{color:#68705f;font-size:13px}.acties{display:flex;gap:8px}@media(max-width:700px){.grid{grid-template-columns:1fr}}</style></head><body><div class="top"><div class="topin"><a href="./">← Terug naar beheer</a><span>Vaste historie: <?=count($vast)?> regels</span></div></div><main class="wrap"><h1>Changelog</h1><p class="meta">De vaste ontwikkelaarshistorie uit de repository is alleen-lezen. Hieronder beheer je alleen eigen verenigingsregels.</p><?php if($melding!==''):?><div class="melding <?=beheerEditorEsc($type)?>"><?=beheerEditorEsc($melding)?></div><?php endif;?><section class="kaart"><h2>Regel toevoegen</h2><form method="post"><input type="hidden" name="csrf" value="<?=beheerEditorEsc($csrfToken)?>"><input type="hidden" name="actie" value="toevoegen"><div class="grid"><div class="veld"><label>Datum</label><input name="datum" value="<?=date('d-m-Y')?>"></div><div class="veld"><label>Categorie</label><select name="cat"><?php foreach(['nieuw'=>'Nieuw','verbeterd'=>'Verbeterd','opgelost'=>'Opgelost','beveiliging'=>'Beveiliging','onderhoud'=>'Onderhoud'] as $k=>$v):?><option value="<?=$k?>"><?=$v?></option><?php endforeach;?></select></div></div><div class="veld"><label>Korte omschrijving</label><input name="titel" maxlength="120"></div><div class="veld"><label>Toelichting</label><textarea name="tekst" maxlength="500"></textarea></div><button class="btn" type="submit">Toevoegen</button></form></section><h2>Eigen regels (<?=count($eigen)?>)</h2><?php if(!$eigen):?><p class="meta">Nog geen eigen regels.</p><?php endif;?><?php foreach($eigen as $r):$id=(string)($r['id']??'');?><section class="kaart"><form method="post"><input type="hidden" name="csrf" value="<?=beheerEditorEsc($csrfToken)?>"><input type="hidden" name="id" value="<?=beheerEditorEsc($id)?>"><div class="grid"><div class="veld"><label>Datum</label><input name="datum" value="<?=beheerEditorEsc(beheerEditorDatumNl($r['datum']??''))?>"></div><div class="veld"><label>Categorie</label><select name="cat"><?php foreach(['nieuw'=>'Nieuw','verbeterd'=>'Verbeterd','opgelost'=>'Opgelost','beveiliging'=>'Beveiliging','onderhoud'=>'Onderhoud'] as $k=>$v):?><option value="<?=$k?>"<?=$k===($r['cat']??'')?' selected':''?>><?=$v?></option><?php endforeach;?></select></div></div><div class="veld"><label>Korte omschrijving</label><input name="titel" maxlength="120" value="<?=beheerEditorEsc($r['titel']??'')?>"></div><div class="veld"><label>Toelichting</label><textarea name="tekst" maxlength="500"><?=beheerEditorEsc($r['tekst']??'')?></textarea></div><div class="acties"><button class="btn" name="actie" value="bewerken" type="submit">Opslaan</button><button class="btn danger" name="actie" value="verwijderen" type="submit" onclick="return confirm('Deze eigen changelogregel verwijderen?')">Verwijderen</button></div></form></section><?php endforeach;?></main></body></html>
